    rows = len(grid)
    cols = len(grid[0])

    def is_valid(row, col):
        return 0 <= row < rows and 0 <= col < cols and grid[row][col] != '#'

    def find_path(current, path):
        if current == goal:
            return path + [current]

        row, col = current
        neighbors = [(row - 1, col), (row + 1, col), (row, col - 1), (row, col + 1)]

        for neighbor_row, neighbor_col in neighbors:
            if is_valid(neighbor_row, neighbor_col) and (neighbor_row, neighbor_col) not in path:
                new_path = find_path((neighbor_row, neighbor_col), path + [current])
                if new_path:
                    return new_path

        return []

    if not is_valid(start[0], start[1]) or not is_valid(goal[0], goal[1]):
        return []

    if start == goal:
        return [start]

    return find_path(start, [])
