        for r, c in neighbors:
            if is_valid(r, c):
                if dfs(r, c):
                    return True

        path.pop()
        return False

    if not is_valid(start[0], start[1]) or not is_valid(goal[0], goal[1]):
        return []

    if start == goal:
        return [start]

    if dfs(start[0], start[1]):
        return path
    else:
        return []
